driver.get("https://exemplo.com/pedidos");

// a lista ainda esta sendo buscada no servidor
driver.findElement(By.id("primeiro-pedido")).click();
// NoSuchElementException -- as vezes

// nunca faca isto
Thread.sleep(3000);
driver.findElement(By.id("primeiro-pedido")).click();

// lento quando a tela e rapida,
// e insuficiente quando ela demora 3,5s

WebDriverWait espera =
    new WebDriverWait(driver, Duration.ofSeconds(10));

WebElement botao = espera.until(
    ExpectedConditions.elementToBeClickable(By.id("primeiro-pedido")));

botao.click();

// existe, mas esta dentro de um menu fechado
espera.until(ExpectedConditions
    .presenceOfElementLocated(By.id("sair")));
driver.findElement(By.id("sair")).click();
// ElementNotInteractableException

// espere pelo que voce vai FAZER
espera.until(ExpectedConditions
    .elementToBeClickable(By.id("sair"))).click();
